// The hex grid and GeoJSON must match tools/coverage-merge.py exactly, or
// contributed files won't line up with (or will be rejected by) the public map.
// golden.json is generated by that script's own functions:
//     python3 android/mesh/src/test/resources/coverage/make_golden.py
package org.nomadpocket.mesh

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.File

class CoverageGoldenTest {
    private val golden: JSONObject by lazy {
        val stream = javaClass.classLoader!!.getResourceAsStream("coverage/golden.json") ?: error("golden.json missing")
        JSONObject(stream.bufferedReader().readText())
    }

    @Test fun cellSizeMatches() {
        assertEquals(golden.getDouble("cell_size"), CoverageShare.CELL_SIZE, 0.0)
    }

    @Test fun hexOfAndCornersMatchThePythonGrid() {
        val points = golden.getJSONArray("points")
        assertTrue(points.length() >= 20)
        for (i in 0 until points.length()) {
            val p = points.getJSONObject(i)
            val lat = p.getDouble("lat")
            val lon = p.getDouble("lon")
            val (q, r) = CoverageShare.hex(lat, lon)
            assertEquals("q for $lat,$lon", p.getInt("q"), q)
            assertEquals("r for $lat,$lon", p.getInt("r"), r)
            val corners = CoverageShare.corners(q, r)
            val expected = p.getJSONArray("corners")
            for (k in 0 until 6) {
                val e = expected.getJSONArray(k)
                assertEquals("corner $k lon at $lat,$lon", e.getDouble(0), corners[k].second, 1e-9)
                assertEquals("corner $k lat at $lat,$lon", e.getDouble(1), corners[k].first, 1e-9)
            }
            // The exported ring (rounded to 1e-6, closed) is identical.
            val ring = JSONObject(CoverageShare.geoJSON(listOf(cell(q, r)))).getJSONArray("features").getJSONObject(0)
                .getJSONObject("geometry").getJSONArray("coordinates").getJSONArray(0)
            assertSame("ring at $lat,$lon", p.getJSONArray("ring"), ring)
        }
    }

    @Test fun geoJSONMatchesToGeojson() {
        val cells = golden.getJSONArray("cells")
        val list = (0 until cells.length()).map { i ->
            val c = cells.getJSONObject(i)
            val pings = c.getJSONArray("pings")
            CoverageShare.Cell(
                q = c.getInt("q"), r = c.getInt("r"), count = c.getInt("count"),
                bestSNR = if (c.isNull("best_snr")) null else c.getDouble("best_snr").toFloat(),
                firmwares = (0 until c.getJSONArray("firmware").length()).map { firmwareOf(c.getJSONArray("firmware").getString(it))!! }.toSet(),
                pingsReached = pings.getInt(0), pingsRelayed = pings.getInt(1), pingsNone = pings.getInt(2),
                firstMonth = c.getString("first_month"), lastMonth = c.getString("last_month"),
            )
        }.sortedWith(compareBy({ it.q }, { it.r })) // cells() returns them in this order
        val out = CoverageShare.geoJSON(list)
        assertSame("document", golden.getJSONObject("geojson"), JSONObject(out))
        // Kept for a manual `python3 tools/coverage-merge.py --check` run.
        File("build").takeIf { it.isDirectory }?.let { File(it, "coverage-export-sample.geojson").writeText(out) }
    }

    private fun cell(q: Int, r: Int) = CoverageShare.Cell(q, r, 1, null, setOf(Firmware.MESHTASTIC), firstMonth = "2026-01", lastMonth = "2026-01")

    /** Deep JSON equality; numbers compare as doubles (Python writes 400.0, we write 400). */
    private fun assertSame(where: String, expected: Any?, actual: Any?) {
        when (expected) {
            is JSONObject -> {
                if (actual !is JSONObject) fail("$where: expected an object, got $actual")
                actual as JSONObject
                assertEquals("$where: keys", expected.keys().asSequence().toSet(), actual.keys().asSequence().toSet())
                for (k in expected.keys()) assertSame("$where.$k", expected.get(k), actual.get(k))
            }
            is JSONArray -> {
                if (actual !is JSONArray) fail("$where: expected an array, got $actual")
                actual as JSONArray
                assertEquals("$where: length", expected.length(), actual.length())
                for (i in 0 until expected.length()) assertSame("$where[$i]", expected.get(i), actual.get(i))
            }
            is Number -> {
                if (actual !is Number) fail("$where: expected $expected, got $actual")
                assertEquals(where, expected.toDouble(), (actual as Number).toDouble(), 0.0)
            }
            else -> assertEquals(where, expected, actual)
        }
    }
}
